//
// Tcl's own library scripts compiled into the binary
// (openspec/changes/m4-scripting/design.md D3): init.tcl, clock.tcl and the
// pure-Tcl packages, message catalogs, time zones and encodings of Tcl
// 8.6.16's library/ directory. The table is generated by cmake/Tcl.cmake;
// the project interpreter evaluates init.tcl from it and serves the rest
// under kVirtualLibraryRoot, so no Tcl file is ever read from the host.
//
// Owner: TCL (design D2); declared by the M4 scaffold.

#pragma once

#include <optional>
#include <span>
#include <string_view>

namespace hefesto::script {

/// One file of Tcl's library/ directory.
struct EmbeddedFile {
  std::string_view path;     // relative to library/, '/'-separated: "init.tcl", "msgcat/msgcat.tcl"
  std::string_view content;  // the file's bytes
};

/// The value of `tcl_library` (and `info library`) in every project
/// interpreter: a path that exists only inside the interpreter's filesystem
/// layer, never on the host.
inline constexpr std::string_view kVirtualLibraryRoot = "/__hefesto_embedded__/tcl8.6";

/// Every embedded file, sorted by path.
[[nodiscard]] std::span<const EmbeddedFile> embedded_library() noexcept;

/// The embedded file at `path` (relative to library/), or nullopt.
[[nodiscard]] std::optional<std::string_view> find_embedded_file(std::string_view path) noexcept;

}  // namespace hefesto::script
